// A run as the tests set it up, and the view the CLI writes for it. Not a test file.
//
// The mod reads only `.temper/view.json` (ADR 0013). The tests keep the CLI's own state as the CLI does (build-state.json,
// gates.json, overrides.json, the spec files), and the test world stands in for the CLI: `deriveView` makes the view
// from that state, starting from the CLI's real output (scripts/selftest/view-fixtures.ts, generated by the CLI itself)
// for the stage and the verdict, with the run's own ids, steps, marks, criteria and findings filled in.

import { VIEWS } from '../../scripts/selftest/view-fixtures'

export const SPEC = '.temper/specs/pw'

// Far in the future so a verdict is always newer than the run's start event.
export const LATER = '2999-01-01T00:00:00Z'

export const INTENT = [
  '# Intent: Password reset by email',
  '',
  '### Success Criteria',
  '',
  ...[1, 2, 3, 4, 5].map(n => `- [ ] AC-0${n} [required]: criterion ${n} (source: test)`),
  '',
].join('\n')

export const PLAN = ['### Files to Modify', '', '| File | Change |', '|---|---|', '| `src/app.ts` | edit |', ''].join('\n')

// Seven tasks; the first two have a ticked row, so the third is current.
export const TASKS = [
  '## Tasks',
  ...[1, 2, 3, 4, 5, 6, 7].flatMap(n => [`### Task ${n}: t${n}`, n <= 2 ? '- [x] done' : '- [ ] open']),
  '',
].join('\n')

export type RunOptions = {
  nextStage?: string
  complexity?: string
  gates?: Record<string, 'PASS' | 'FAIL'>
  passedCriteria?: string[]
}

export function runFiles(o: RunOptions = {}): Record<string, string> {
  const gates: Record<string, unknown> = {}
  for (const [stage, verdict] of Object.entries(o.gates ?? {})) gates[stage] = { verdict, ts: LATER, requirements: [{ name: 'tests pass', pass: verdict === 'PASS', detail: verdict === 'PASS' ? 'ok' : '2 tests fail' }] }
  const files: Record<string, string> = {
    '.temper/build-state.json': JSON.stringify({ spec: 'pw', spec_path: SPEC, command: 'temper', next_stage: o.nextStage ?? 'plan', run_id: 'run-pw', step: 3, ...(o.complexity ? { complexity: o.complexity } : {}) }),
    '.temper/gates.json': JSON.stringify(gates),
    [`${SPEC}/intent.md`]: INTENT,
    [`${SPEC}/plan.md`]: PLAN,
    [`${SPEC}/tasks.md`]: TASKS,
  }
  if (o.passedCriteria) {
    files['.temper/status.json'] = JSON.stringify({
      ts: 't',
      criteria: [1, 2, 3, 4, 5].map(n => ({ id: `AC-0${n}`, priority: 'required', status: o.passedCriteria?.includes(`AC-0${n}`) ? 'passed' : 'open', evidence: [] })),
    })
  }
  return files
}

type J = Record<string, unknown>

const json = (text: string | undefined): unknown => {
  if (text === undefined) return undefined
  try {
    return JSON.parse(text)
  } catch {
    return undefined
  }
}

const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v)) as T

export const view = (name: string): J => clone(VIEWS[name] as J)

const SEQ = ['intent', 'plan', 'design', 'build', 'review', 'check', 'commit']

// The backticked paths of the plan's Files tables and the tasks' File lines, as the CLI reads them (scripts/flow.py).
export function planFiles(plan: string, tasks: string): string[] {
  const out: string[] = []
  let on = false
  for (const line of plan.split('\n')) {
    if (/^#{2,6}\s/.test(line)) on = /files to (?:create|modify)/i.test(line)
    else if (on && line.trim().startsWith('|')) for (const m of (line.split('|')[1] ?? '').matchAll(/`([^`]+)`/g)) out.push(m[1] as string)
  }
  for (const line of tasks.split('\n')) if (/^\*\*File:\*\*/.test(line)) for (const m of line.matchAll(/`([^`]+)`/g)) out.push(m[1] as string)
  return [...new Set(out)]
}

// Sets the run id and the step on a question, its More options, its accept question and its reason questions.
function stamp(q: unknown, id: string, step: number): void {
  if (typeof q !== 'object' || q === null) return
  const o = q as J
  if ('step' in o) o.step = step
  if ('run_id' in o) o.run_id = id
  stamp(o.more, id, step)
  stamp(o.accept, id, step)
}

// The view the CLI writes for the state in `get` (a file reader), or null when there is no run state. Text that is not
// JSON stands for a view.json the CLI could not have written whole (a broken state file).
export function deriveView(get: (path: string) => string | undefined): string | null {
  const bsText = get('.temper/build-state.json')
  if (bsText === undefined) return null
  const bs = json(bsText) as J | undefined
  if (typeof bs !== 'object' || bs === null || typeof bs.next_stage !== 'string') return '{"version": 1, "run": '
  const gates = (json(get('.temper/gates.json')) ?? {}) as Record<string, { verdict?: string; requirements?: Array<{ name: string; pass: boolean; detail: string }> }>
  const overrides = (json(get('.temper/overrides.json')) ?? []) as Array<{ stage?: string; reason?: string; by?: string }>
  const config = get('.claude/temper.config') ?? ''
  const autonomy = /autonomy:\s*\n\s+enabled:\s*true/.test(config)
  const designOn = /phases:\s*\n\s+design:\s*true/.test(config)
  const stage = bs.next_stage === 'done' ? 'commit' : bs.next_stage
  const command = typeof bs.command === 'string' ? bs.command : 'temper'
  const spec = typeof bs.spec_path === 'string' ? bs.spec_path : SPEC
  const slug = typeof bs.spec === 'string' ? bs.spec : 'pw'
  const id = typeof bs.run_id === 'string' ? bs.run_id : 'run-pw'
  const step = typeof bs.step === 'number' ? bs.step : 0
  const skipped = (s: string) => overrides.find(o => o.stage === s)
  const verdict = (s: string): string | undefined => gates[s]?.verdict
  const result = verdict(stage) === 'PASS' || skipped(stage) ? 'pass' : verdict(stage) === 'FAIL' ? 'fail' : 'work'
  const armed = bs.run_mode === 'autonomous' && autonomy
  const design = stage === 'design' || verdict('design') !== undefined || ((bs.complexity === 'medium' || bs.complexity === 'complex') && designOn)
  let name: string
  if (command === 'fix') name = 'fix-rca'
  else if (armed && `armed-${stage}-${result}` in VIEWS) name = `armed-${stage}-${result}`
  else if (stage === 'plan' && result === 'pass' && autonomy) name = 'plan-pass-autonomy'
  else if (stage === 'plan' && result === 'pass' && design) name = 'design-plan-pass'
  else name = `${stage}-${result}`
  // A stage the CLI does not have: the view names it as the state does, and the mod cannot tell where the run is.
  const known = name in VIEWS
  const v = view(known ? name : 'intent-work')
  const run = v.run as J
  const intent = get(`${spec}/intent.md`) ?? ''
  Object.assign(run, { id, step, slug, spec, command, stage, title: /^#\s+(?:Intent:\s*)?(.+?)\s*$/m.exec(intent)?.[1] ?? slug, mode: armed ? 'autonomous' : 'interactive', complexity: bs.complexity ?? null })
  const files = planFiles(get(`${spec}/plan.md`) ?? '', get(`${spec}/tasks.md`) ?? '')
  const noSpec = ['intent.md', 'plan.md', 'tasks.md', 'design.md'].every(n => get(`${spec}/${n}`) === undefined)
  v.guard = {
    ...(v.guard as J),
    stage,
    spec,
    slug,
    fix_run: command === 'fix',
    grouped: get('.temper/groups.json') !== undefined,
    armed,
    autonomy_enabled: autonomy,
    // The files the person approved, as the CLI records them when the run leaves Plan; before that, the plan's.
    plan_files: Array.isArray(bs.approved_files) ? bs.approved_files : files,
    step,
    run_id: id,
    trivial_exit: stage === 'intent' && step === 0 && Object.keys(gates).length === 0 && overrides.length === 0 && noSpec,
  }
  stamp(v.ask, id, step)
  stamp(v.restart, id, step)
  // The stages of the run: a skipped, failed or passed mark before the stage the run is at, as the CLI marks them.
  const seq = SEQ.filter(s => s !== 'design' || design)
  const here = seq.indexOf(stage)
  v.stages = seq.map((s, i) => {
    const sk = skipped(s)
    const vd = verdict(s) ?? null
    const mark = here < 0 ? 'todo' : i < here ? (sk && vd !== 'PASS' ? 'skipped' : vd === 'FAIL' ? 'failed' : 'passed') : i === here ? 'here' : 'todo'
    const row: J = { id: s, label: s.charAt(0).toUpperCase() + s.slice(1), mark, verdict: vd, failed: (gates[s]?.requirements ?? []).filter(q => !q.pass) }
    if (sk) row.skipped = { reason: sk.reason ?? '', by: sk.by ?? '' }
    return row
  })
  v.skips = overrides.map(o => ({ stage: o.stage ?? '', reason: o.reason ?? '', by: o.by ?? '' }))
  const status = json(get('.temper/status.json')) as { criteria?: Array<{ id: string; status: string }> } | undefined
  const ids = [...intent.matchAll(/^\s*-\s*\[[ xX]\]\s*(AC-\d+)\s*\[(required|optional)\]:\s*(.*)$/gm)]
  v.criteria = ids.map(m => ({ id: m[1], priority: m[2], status: status?.criteria?.find(c => c.id === m[1])?.status ?? 'open', text: (m[3] ?? '').trim(), evidence: [] }))
  // The usage rows, summed as the CLI sums them.
  const usage = json(get('.temper/usage.json'))
  if (Array.isArray(usage)) {
    const rows = usage.filter((r): r is J => typeof r === 'object' && r !== null && !Array.isArray(r))
    const n = (x: unknown): number => (typeof x === 'number' && Number.isInteger(x) ? x : 0)
    const by = (key: string): J => {
      const out: Record<string, { tokens: number; ms: number; runs: number }> = {}
      for (const r of rows) {
        const b = (out[typeof r[key] === 'string' && r[key] !== '' ? (r[key] as string) : 'unknown'] ??= { tokens: 0, ms: 0, runs: 0 })
        b.runs += 1
        b.tokens += n(r.tokens)
        b.ms += n(r.ms)
      }
      return out
    }
    v.usage = { tokens: rows.reduce((t, r) => t + n(r.tokens), 0), ms: rows.reduce((t, r) => t + n(r.ms), 0), by_stage: by('stage'), by_model: by('model') }
  }
  const review = json(get('.temper/evidence/review.json'))
  if (Array.isArray(review)) {
    v.findings = (review as J[])
      .map((r, i) => ({ r, i }))
      .filter(({ r }) => typeof r.severity === 'string' && r.claim !== 'review completed')
      .map(({ r, i }) => {
        const m = /^\s*([\w./@-]+\.\w+):(\d+)/.exec(String(r.claim ?? ''))
        return { id: i + 1, severity: String(r.severity).toLowerCase(), claim: String(r.claim ?? ''), file: m?.[1] ?? null, line: m ? Number(m[2]) : null, state: r.accepted_reason || r.accepted ? 'accepted' : r.resolved || r.fixed_by ? 'resolved' : 'open', label: r.label ?? null }
      })
  }
  return JSON.stringify(v)
}

// The question `temper next --json` gives now, as Claude must ask it: `which` picks the More options question, the
// accept question, the reason question of an option, or the Temper resume question.
export function questionOf(viewText: string, which: { more?: boolean; accept?: boolean; reasonOf?: string; restart?: boolean } = {}): { header: string; question: string; options: Array<{ label: string; description: string }> } {
  const v = JSON.parse(viewText) as J
  if (which.restart) {
    const r = v.restart as J
    return { header: String(r.header), question: String(r.question), options: (r.options as J[]).map(o => ({ label: String(o.label), description: String(o.description) })) }
  }
  let ask = v.ask as J
  if (which.more) ask = ask.more as J
  if (which.accept) ask = ask.accept as J
  if (which.reasonOf !== undefined) {
    const all = [ask, ask.more, ask.accept].filter((a): a is J => typeof a === 'object' && a !== null)
    for (const a of all) {
      const o = (a.options as J[]).find(x => x.label === which.reasonOf)
      if (o?.reason_question) return o.reason_question as never
    }
    throw new Error(`no reason question for ${which.reasonOf}`)
  }
  return ask.question as never
}

// The calls and steps of one option of the question a fixture view asks (`which` as for questionOf), as the CLI wrote
// them: what the person's answer lets through.
export function optionCalls(name: string, label: string, which: { more?: boolean; accept?: boolean } = {}): string[] {
  let ask = (VIEWS[name] as J).ask as J
  if (which.more) ask = ask.more as J
  if (which.accept) ask = ask.accept as J
  const o = (ask.options as J[]).find(x => x.label === label)
  if (o === undefined) throw new Error(`no option ${label} in ${name}`)
  return [...((o.calls as string[]) ?? []), ...((o.steps as string[]) ?? [])]
}

// The calls and steps of the CLI's own action in a fixture view (an armed run's move, the commit steps).
export function nextCalls(name: string): string[] {
  const n = (VIEWS[name] as J).next as J
  return [...((n.calls as string[]) ?? []), ...((n.steps as string[]) ?? [])]
}
